mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T1.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_NAME finprodName, T4.BOARD board, T1.PS ps, T1.TRADE_MARKET tradeMarket, T7.DEAL_MODE dealMode, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, T1.ENTRUST_NUM entrustNum, T1.PRICE price, T1.ENTRUST_AMT entrustAmt, T1.REMARK remark, T1.PRICE_MODEL priceModel, NVL(T5.FINISH_AMT,0) finishAmt, round(NVL(T5.FINISH_AMT,0)/NVL(T1.ENTRUST_NUM,T1.ENTRUST_AMT),2) transactioncom FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN FIN_PRODUCT_ADD T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(NVL(FINISH_AMT,0)) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T2.PORTFOLIO_ID = T6.PORTFOLIO_ID INNER JOIN ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID
AND T6.USER_ID = #{userId}
AND (T2.PORTFOLIO_ID IN
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
#{prot}
)
AND T1.CCY = #{ccy}
AND (T3.FINPROD_MARKET_ID like concat('%',concat(#{finprodId},'%')) OR T3.FINPROD_NAME like concat('%',concat(#{finprodId},'%')))
AND T1.PS=#{ps}
AND T1.TRADE_MARKET=#{tradeMarket}
AND T7.DEAL_MODE=#{dealMode}
AND T4.BOARD = #{board}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.VDATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.PRICE_MODEL = #{priceModel}
AND T3.FINPROD_TYPE2 = #{finprodType2}
order by T1.ENTRUST_ID DESC

SELECT FINPROD_MARKET_ID code, FINPROD_MARKET_ID name, FINPROD_NAME shortName, FINPROD_ID hidCode FROM FIN_PRODUCT
FINPROD_MARKET_ID IS NOT NULL AND FINPROD_TYPE2 = #{planasset}
and (FINPROD_MARKET_ID like concat('%',concat(#{param},'%')) or FINPROD_NAME like concat('%',concat(#{param},'%')))

SELECT T1.PORTFOLIO_ID id, T1.PORTFOLIO_NAME text FROM PTL_PORTFOLIO T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID AND T2.USER_ID = #{userId}
and T1.PORTFOLIO_ID = #{initValue}
and (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) or T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))

SELECT T1.FINPROD_MARKET_ID id, T1.FINPROD_NAME text, T1.FINPROD_ID, T1.CALENDAR_ID, T1.CCY, T2.BOARD, T1.TRADE_MARKET, T1.VDATE, T1.MDATE FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_ADD T2 ON T1.FINPROD_ID = T2.FINPROD_ID
T1.FINPROD_MARKET_ID IS NOT NULL AND T1.FINPROD_TYPE2 = #{planasset}
and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) or T1.FINPROD_NAME like concat('%',concat(#{search},'%')))
and T1.FINPROD_MARKET_ID = #{initValue}

		select
			T.FINPROD_ID       id,
			T.FINPROD_NAME     text
		from FIN_PRODUCT T


             AND T.FINPROD_TYPE2 = #{finprodType2}


              AND T.IS_CHL = #{isChl}

select
  AMOUNT
from PTL_CASH_POSITION
where
	(HODING_TYPE=#{POSITION_TYPE_01} or HODING_TYPE=#{POSITION_TYPE_03}) and PORTFOLIO_ID=#{portfolioId}
	and CDATE=(select cur_date from sys_date) and CHL_FINPROD_ID=#{TongDao}

SELECT A.ACCT_NO hidCode, A.ACCT_NO code, B.SEC_ACCT_NAME name, B.SEC_ACCT_NAME shortName FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID
PORTFOLIO_ID = #{portfolioId}
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.ACCT_NO = #{initValue}
AND B.TRADE_PLACE = #{tradeMarket}
